function noncePlayground(){
 return `<section class="panel nonce-lab" id="nonce-lab">
 <div class="studio-board__eyebrow">EXPERIMENTO DE PRUEBA DE TRABAJO · UNIDAD 3</div>
 <div class="nonce-lab__head"><div><h2>Nonce: cambiar un número para buscar un hash aceptable</h2><p>El <b>nonce</b> es uno de los seis campos del encabezado. El minero lo modifica y vuelve a calcular el hash para comprobar si el resultado queda por debajo del límite exigido. No está descifrando un secreto ni cambiando la cantidad de bitcoins enviados.</p></div><div class="nonce-lab__flag">0 → 1 → 2<br/><small>números de prueba</small></div></div>
 <div class="nonce-lab__steps"><div><small>PASO 01</small><b>Bloque candidato</b><p>Transacciones y campos de encabezado.</p></div><span aria-hidden="true">→</span><div><small>PASO 02</small><b>Variar el nonce</b><p>Probar valores sucesivos.</p></div><span aria-hidden="true">→</span><div><small>PASO 03</small><b>Comprobar el hash</b><p>¿Cumple la dificultad fijada?</p></div></div>
 <div class="nonce-lab__experiment">
 <div class="nonce-lab__experiment-head"><div><span>DESAFÍO DEL AULA</span><strong>Encontrar un SHA-256 que comience con «00»</strong></div><span class="nonce-lab__odds">≈ 1 de 256 intentos</span></div>
 <p>Usamos el texto de un bloque ficticio y cambiamos su nonce. La condición del prefijo «00» es <b>inventada para aprender</b>: Bitcoin real calcula dos veces SHA-256 del encabezado de 80 bytes y compara su valor numérico con un objetivo.</p>
 <button type="button" class="btn" id="nonceSearch">Iniciar búsqueda de nonce →</button>
 <div id="nonceResult" class="nonce-lab__result" role="status" aria-live="polite">Presioná «Iniciar búsqueda» para visualizar intentos y resultado.</div>
 </div>
 <p class="studio-footnote">No se mina Bitcoin, no se crea ninguna criptomoneda ni se usa capacidad computacional para fines externos. <a href="https://bitcoindevelopers.org/docs/reference/block-chain-ref/" target="_blank" rel="noopener noreferrer">Referencia técnica: encabezado Bitcoin y campo nonce →</a></p></section>`;
}
async function renderNonceAttempt(){
 const btn=document.getElementById("nonceSearch"),out=document.getElementById("nonceResult");
 if(!btn||!out)return;
 if(!globalThis.crypto?.subtle){out.textContent="La demostración necesita el navegador en HTTPS y Web Crypto.";return;}
 btn.disabled=true;btn.textContent="Buscando nonce…";
 const enc=new TextEncoder(),samples=[];let found=null,attempts=0;
 try{
  for(let nonce=0;nonce<5000;nonce++){
   const bytes=new Uint8Array(await crypto.subtle.digest("SHA-256",enc.encode("LAST Lab Campus | bloque de ejemplo | nonce="+nonce)));
   const first=bytes[0].toString(16).padStart(2,"0");
   const passed=bytes[0]===0;
   attempts++;
   if(nonce<5||passed)samples.push({nonce,first,passed});
   if(passed){found={nonce,hash:Array.from(bytes).map(b=>b.toString(16).padStart(2,"0")).join("")};break;}
   if(nonce>0 && nonce%80===0){out.textContent="Probados "+attempts+" valores…";await new Promise(resolve=>setTimeout(resolve,0));}
  }
  const rows=samples.slice(0,5).map(x=>`<div class="nonce-lab__row"><span>nonce ${x.nonce}</span><code>${x.first}…</code><small>${x.passed?"✓ Cumple":"✕ No cumple"}</small></div>`).join("");
  if(found){out.innerHTML=`<div class="nonce-lab__table">${rows}</div><div class="nonce-lab__success"><strong>✓ Encontrado tras ${attempts} intentos</strong><span>nonce = ${found.nonce}</span><code>${found.hash}</code><p>La comprobación es inmediata; encontrar el valor exigió probar diferentes candidatos. Este ejercicio <b>no</b> reproduce la dificultad ni el mecanismo de minería de Bitcoin.</p></div>`;}
  else{out.textContent="No se encontró un valor en 5.000 intentos. Podés intentarlo nuevamente con otro texto de ejemplo; en una búsqueda real no está garantizado un número fijo de intentos.";}
 }catch(e){out.textContent="No se pudo ejecutar el experimento local en este navegador.";}
 finally{btn.disabled=false;btn.textContent="Repetir la búsqueda →";}
}
function bindNonceLab(){
 const btn=document.getElementById("nonceSearch");if(btn)btn.addEventListener("click",renderNonceAttempt);
}
